    agriculture=["Dairy farming and alpine dairy cattle (Simmental and Brown Swiss cows producing world-famous cheeses)", "Artisanal cheeses with PDO protection (Gruyère, Emmentaler, Appenzeller, Raclette du Valais, Tête de Moine)", "Wine viticulture along steep terraces (Lavaux vineyard terraces on Lake Geneva - UNESCO; Valais: Fendant / Chasselas, Petite Arvine; Ticino: Merlot)", "Apples, stone fruits, and Swiss chocolate production", "Cereals and sugar beets in the Mittelland"],
    naturalResources=["Immense hydroelectric potential (storing over 50% of Europe's alpine reservoir energy)", "Arable land in the Swiss Plateau (Mittelland)", "Limestone, granite, and gravel", "Pristine alpine water springs (mineral water: Henniez, Valser)", "Stunning alpine and lacustrine geography"],
    energy="Over 75% renewable domestic electricity: Hydroelectric power (generating ~60% of national electricity across 680 plants: Grande Dixence dam - world's tallest gravity dam at 285 m), Nuclear power (Beznau, Gösgen, and Leibstadt operating 4 commercial reactors producing ~32%), expanding solar PV and biomass; net zero carbon emissions targeted by 2050.",
    exports=["Pharmaceuticals, vaccines, and packaged medicaments (over 38% of total exports)", "Fine luxury watches and precision timepieces (Rolex, Patek Philippe, Omega)", "Precious metals and refined gold bullion (Switzerland refines over 70% of the world's gold in refineries like Valcambi, Argor-Heraeus, PAMP)", "Industrial machinery, electronics, and precision tools", "Chemicals and fragrance compounds (Givaudan)", "Swiss chocolate (Lindt), dairy, and Nespresso coffee"],
